toolCalls.target:
text(await tools.exec_command({cmd:"node --input-type=module <<'NODE'
import fs from 'node:fs';
import path from 'node:path';
for (const root of ['~/.npm/_npx', '~/.bun/install/cache']) {
  if (!fs.existsSync(root)) continue;
  for (const entry of fs.readdirSync(root)) {
    const base = path.join(root, entry);
    const candidates = root.endsWith('_npx')
      ? ['node_modules/@biomejs/cli-darwin-arm64/biome', 'node_modules/@biomejs/biome/bin/biome'].map(p => path.join(base,p))
      : entry.startsWith('@biomejs') ? [path.join(base,'biome'),path.join(base,'bin

